export function getModelPreviewUrl(modelFile) {
  if (!modelFile) {
    return null;
  }

  const normalized = modelFile.trim();
  const previewUrl = previewMap[normalized];
  if (previewUrl) {
    return previewUrl;
  }

  // Return a default placeholder for unknown models
  return "/assets/products/earrings.png";
}